import { Component, h, Listen, Method, Prop, State } from '@stencil/core';

// Component ui-options: Deprecated
@Component({
  tag: 'ui-options',
  styleUrl: 'ui-options.css',
  shadow: true
})
export class UiOptionsComponent {
  optionsElement: HTMLDivElement;
  @Prop() closable: boolean = false;
  @Prop() closableItem: boolean = false;
  @State() isOpen: boolean;

  onCloseItem() {
    if (this.closableItem) {
      this.isOpen = false;
    }
  }

  @Method()
  async close() {
    this.isOpen = false;
  }

  @Listen('click', { target: 'document' })
  checkForClickOutside(ev: PointerEvent): void {
    const path = ev.composedPath();
    if (this.isOpen && !path.includes(this.optionsElement) && this.closable) {
      this.isOpen = false;
    }
  }

  toggleCollapse(): void {
    this.isOpen = !this.isOpen;
  }

  render() {
    return (
      <div
        ref={el => (this.optionsElement = el)}
        class={`css-options w-12 h-16 bg-primary text-white js-collapse flex items-center flex-row-reverse relative cursor-pointer ${this.isOpen ? 'is-open' : ''}`}>
        <div class="css-collapse-header js-collapse-header w-full h-full flex items-center justify-center" onClick={() => this.toggleCollapse()}>
          <i class="icon-3-dots-vertical text-2xl leading-none show-icon"></i>
          <i class="icon-close text-2xl leading-none hidden hidden-icon"></i>
        </div>

        <div class="css-options-body js-collapse-body hidden absolute top-0 right-12 h-full bg-primary items-center">
          <ul class="flex items-center h-full" onClick={() => this.onCloseItem()}>
            <slot />
          </ul>
        </div>
      </div>
    );
  }
}
